function loadSave() {
  try {
    const raw = JSON.parse(localStorage.getItem(SAVE_KEY) || "null");
    if (raw && typeof raw === "object") {
      raw.evs = raw.evs || { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 };
      raw.totalKills = raw.totalKills || 0;
      raw.bossKills = raw.bossKills || 0;
      raw.maxLevel = raw.maxLevel || 5;
      raw.maxTime = raw.maxTime || 0;
      raw.totalCompanions = raw.totalCompanions || 0;
      raw.tmsLearned = raw.tmsLearned || 0;
      raw.totalVitamins = raw.totalVitamins || 0;
      raw.forceUnlockAll = !!raw.forceUnlockAll;
      raw.selectedChar = raw.selectedChar || 1;
      raw.selectedStage = raw.selectedStage || "forest";
      return raw;
    }
  } catch (e) {}
  return {
    evs: { hp: 0, atk: 0, def: 0, spa: 0, spd: 0, spe: 0 },
    totalKills: 0,
    bossKills: 0,
    maxLevel: 5,
    maxTime: 0,
    totalCompanions: 0,
    tmsLearned: 0,
    totalVitamins: 0,
    forceUnlockAll: false,
    selectedChar: 1,
    selectedStage: "forest"
  };
}
let SAVE = loadSave();
function writeSave() {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(SAVE)); } catch (e) {}
}

function isCharUnlocked(ch) { return SAVE.forceUnlockAll || ch.check(SAVE); }
function isStageUnlocked(st) { return SAVE.forceUnlockAll || st.check(SAVE); }
function getEvBonusPct(statKey) {
  if (SAVE.forceUnlockAll) return 15;
  return Math.min(15, Math.floor((SAVE.evs && SAVE.evs[statKey]) || 0));
}

function getTypeEffectiveness(moveType, defTypes) {
  const atkIdx = TYPE_LIST.indexOf(moveType);
  if (atkIdx < 0 || !defTypes) return 1.0;
  let mul = 1.0;
  for (let i = 0; i < defTypes.length; i++) {
    const defIdx = TYPE_LIST.indexOf(defTypes[i]);
    if (defIdx >= 0) {
      const val = TYPE_CHART[atkIdx][defIdx];
      mul *= (val === 0 ? 0.35 : val);
    }
  }
  return mul;
}

