// ============================================================================
// Escalating Hardcore Difficulty & Wave Climax Curve (No More 5-Min Easy Mode!)
// ============================================================================
function getTargetEnemyLevel(isBoss = false, isElite = false) {
  if (!RUN) return 4;
  const pLv = RUN.level || 5;
  const timeMin = RUN.time / 60;
  // After 3 minutes, time pressure accelerates sharply so monsters out-scale passive play!
  const lateSurge = Math.max(0, timeMin - 3.0) * 2.2 + Math.pow(Math.max(0, timeMin - 5.0), 1.45) * 2.6;
  const baseLv = Math.round(pLv * 1.02 + timeMin * 1.65 + lateSurge + RUN.stage.lvOffset);
  const offset = isBoss ? 5 : (isElite ? 2 : 0);
  return Math.max(4, baseLv + offset);
}

function computePokemonStats(speciesId, level, isPlayer = false, isBoss = false, runBuffs = null) {
  const entry = POKE_DB[speciesId] || { t: ["normal"], s: [60, 60, 60, 60, 60, 60], bst: 360 };
  const [bHp, bAtk, bDef, bSpa, bSpd, bSpe] = entry.s;

  const coreHp = Math.floor(((2 * bHp + 31) * level) / 100) + level + 10;
  const pLv = RUN ? RUN.level : 5;
  const pEvo = RUN ? RUN.evoStage : 0;
  const timeMin = RUN ? (RUN.time / 60) : 0;

  // Exponential post-4-minute monster fortitude so 5~12 min requires real Hex Super-Weapons & Mega Bursts!
  const timeFortitude = 1 + Math.max(0, timeMin - 2.0) * 0.28 + Math.pow(Math.max(0, timeMin - 4.5), 1.65) * 0.42;
  const evoScale = (1 + pEvo * 0.34 + Math.max(0, pLv - 10) * 0.035) * timeFortitude;

  let maxHp = coreHp;
  if (isPlayer) {
    const evPct = getEvBonusPct("hp") * 0.01;
    const goliathBonus = RUN ? (RUN.goliathHpBonus || 0) : 0;
    const goliathMul = (RUN && RUN.hexes && RUN.hexes.goliath) ? 1.25 : 1.0;
    maxHp = Math.floor(((coreHp * 2.35 + 48) * (1 + evPct) * goliathMul) + goliathBonus);
  } else if (isBoss) {
    maxHp = Math.floor((coreHp * 18.5 + 320) * evoScale);
  } else {
    maxHp = Math.floor((coreHp * 1.65 + 16) * evoScale);
  }

  const statFn = (base, key) => {
    const raw = Math.floor(((2 * base + 31) * level) / 100) + 8;
    if (!isPlayer) {
      const enemyTimeMul = 1 + pEvo * 0.16 + Math.max(0, timeMin - 3.0) * 0.14;
      return Math.floor(raw * enemyTimeMul);
    }
    const hexMight = (RUN && RUN.hexes && RUN.hexes.silver_might && (key === "atk" || key === "spa")) ? 0.18 * RUN.hexes.silver_might : 0;
    const diceBonus = (RUN && RUN.hexes && RUN.hexes.silver_dice) ? 0.08 * RUN.hexes.silver_dice : 0;
    const evMul = 1 + getEvBonusPct(key) * 0.01 + ((runBuffs && runBuffs[key]) || 0) * 0.05 + hexMight + diceBonus;
    return Math.floor(raw * evMul);
  };

  let add = [0, 0, 0, 0, 0, 0];
  // Stat bonus ONLY applies while Ultimate Awakening Burst is actively running!
  if (isPlayer && RUN && RUN.ultActive && RUN.awakening && RUN.awakening.statAdd) {
    add = RUN.awakening.statAdd;
  }
  return {
    types: entry.t,
    bst: entry.bst + (isPlayer && RUN && RUN.ultActive && RUN.awakening ? 110 : 0),
    maxHp: maxHp + Math.floor(add[0] * 3.5),
    atk: statFn(bAtk + add[1], "atk"),
    def: statFn(bDef + add[2], "def"),
    spa: statFn(bSpa + add[3], "spa"),
    spd: statFn(bSpd + add[4], "spd"),
    spe: statFn(bSpe + add[5], "spe")
  };
}

function getMoveSlotById(moveId) {
  if (!RUN || !RUN.moves) return null;
  for (let i = 0; i < RUN.moves.length; i++) {
    if (RUN.moves[i].id === moveId) return RUN.moves[i];
  }
  return null;
}

function hasMoveMod(mSlot, modId) {
  if (!mSlot || !mSlot.mods) return 0;
  let cnt = 0;
  for (let i = 0; i < mSlot.mods.length; i++) {
    if (mSlot.mods[i] === modId) cnt++;
  }
  return cnt;
}

function isMoveSuperWeapon(mSlot) {
  return !!(mSlot && mSlot.mods && mSlot.mods.length >= 3);
}

function computeMoveCooldown(moveId, attackerStats, heldItems = null, mSlot = null) {
  const m = MOVES_DB[moveId];
  if (!m) return 1.1;
  const effPower = m.p * (m.h > 1 ? (m.h > 2 ? 2.2 : 1.6) : 1.0);
  let baseCd = 0.68 + Math.pow(effPower / 42, 0.68) * 0.42;
  if (m.pat === "bible_orbit") baseCd = 2.4;
  else if (m.pat === "santa_hazard" || m.pat === "gravity_well") baseCd = 2.0;
  else if (m.pat === "sonic_boom") baseCd = 0.98;
  else if (m.pat === "fist_flurry" || m.pat === "spear_thrust") baseCd *= 0.84;

  const speFactor = Math.max(0.60, Math.min(1.12, 110 / (85 + attackerStats.spe * 0.45)));
  const clawBonus = heldItems && heldItems.quick_claw ? Math.pow(0.90, heldItems.quick_claw) : 1.0;

  let hexCdMul = 1.0;
  if (mSlot) {
    const oc = hasMoveMod(mSlot, "overclock");
    if (oc > 0) hexCdMul *= Math.pow(0.74, oc);
    const gat = hasMoveMod(mSlot, "gatling");
    if (gat > 0) hexCdMul *= Math.pow(0.48, gat);
    if (isMoveSuperWeapon(mSlot)) hexCdMul *= 0.82;
  }
  if (RUN && attackerStats === RUN.stats) {
    if (RUN.hexes && RUN.hexes.berserker_drive) hexCdMul *= Math.pow(0.82, RUN.hexes.berserker_drive);
    if (RUN.hexes && RUN.hexes.silver_haste) hexCdMul *= Math.pow(0.86, RUN.hexes.silver_haste);
    if (RUN.ultActive) hexCdMul *= 0.65; // Ultimate Awakening Burst gives +35% faster skill fire rate!
  }
  return Math.max(0.24, baseCd * speFactor * clawBonus * hexCdMul);
}

function calculatePokemonDamage(attackerLv, attackerStats, moveId, defenderLv, defenderStats, aoeScale = 1.0, heldItems = null, mSlot = null) {
  const m = MOVES_DB[moveId];
  if (!m) return { dmg: 5, eff: 1.0, isCrit: false, stab: 1.0 };

  const isPhys = m.c === "physical";
  const A = isPhys ? attackerStats.atk : attackerStats.spa;
  const D = Math.max(1, isPhys ? defenderStats.def : defenderStats.spd);

  const isPlayerAtk = (RUN && attackerStats === RUN.stats);
  const isTera = isPlayerAtk && RUN.ultActive && RUN.awakening && RUN.awakening.kind === "tera";
  const stab = attackerStats.types.includes(m.t) ? (isTera ? 2.1 : 1.5) : 1.0;
  const awkMul = (isPlayerAtk && RUN.ultActive) ? 1.45 : 1.0;

  let eff = getTypeEffectiveness(m.t, defenderStats.types);
  if (eff >= 1.9 && heldItems && heldItems.expert_belt) {
    eff *= (1 + 0.25 * heldItems.expert_belt);
  }

  let extraCrit = heldItems && heldItems.scope_lens ? heldItems.scope_lens * 12 : 0;
  let critDmgMul = 1.5;
  if (isPlayerAtk && RUN.hexes && RUN.hexes.jeweled_gauntlet) {
    extraCrit += 30 * RUN.hexes.jeweled_gauntlet;
    critDmgMul = 2.15;
  }
  const isCrit = Math.random() * 100 < ((m.cr || 8) + extraCrit);
  const critMul = isCrit ? critDmgMul : 1.0;

  let modDmgMul = 1.0;
  if (mSlot) {
    modDmgMul *= (1 + mSlot.mods.length * 0.14);
    if (hasMoveMod(mSlot, "colossal") > 0) modDmgMul *= 1.18;
    if (hasMoveMod(mSlot, "reaper") > 0) modDmgMul *= 1.35;
    if (isMoveSuperWeapon(mSlot)) modDmgMul *= 1.32; // ★ Super Weapon 3-socket completion spike!
  }
  if (isPlayerAtk && RUN.hexes && RUN.hexes.berserker_drive) {
    const missingPct = Math.max(0, (1 - RUN.hp / Math.max(1, RUN.maxHp)) * 10);
    modDmgMul *= (1 + missingPct * 0.08 * RUN.hexes.berserker_drive);
  }
  if (!isPlayerAtk && RUN && RUN.hexes && RUN.hexes.trainer_resonance) {
    modDmgMul *= (1 + 0.40 * RUN.hexes.trainer_resonance);
  }

  const randVar = 0.92 + Math.random() * 0.14;
  const baseDmg = (((2 * attackerLv / 5 + 2) * m.p * (A / D)) / 50 + 2);
  const finalDmg = Math.max(1, Math.round(baseDmg * stab * eff * critMul * aoeScale * awkMul * modDmgMul * randVar));
  return { dmg: finalDmg, eff, isCrit, stab };
}

// ============================================================================
// Underlying Engine Optimization #1: Re-Entrant Safe Spatial Hash Grid
// Fixes the nested `queryEnemiesInRadius` shared-array corruption & freeze bug!
// ============================================================================
const GRID_CELL = 96;
const GRID_BUCKETS = new Map();
const GRID_POOL = [];

function clearSpatialGrid() {
  for (const arr of GRID_BUCKETS.values()) {
    arr.length = 0;
    GRID_POOL.push(arr);
  }
  GRID_BUCKETS.clear();
}

function insertEnemyToGrid(e) {
  const cx = Math.floor(e.x / GRID_CELL);
  const cy = Math.floor(e.y / GRID_CELL);
  const key = ((cx & 0xffff) << 16) | (cy & 0xffff);
  let bucket = GRID_BUCKETS.get(key);
  if (!bucket) {
    bucket = GRID_POOL.length > 0 ? GRID_POOL.pop() : [];
    GRID_BUCKETS.set(key, bucket);
  }
  bucket.push(e);
}

// Returns a fresh array per query so nested calls (e.g. executeUnitMove -> hitEnemyWithMove -> bounce) NEVER overwrite an outer loop's array!
function queryEnemiesInRadius(x, y, r) {
  const results = [];
  const pad = r + 38;
  const minCx = Math.floor((x - pad) / GRID_CELL);
  const maxCx = Math.floor((x + pad) / GRID_CELL);
  const minCy = Math.floor((y - pad) / GRID_CELL);
  const maxCy = Math.floor((y + pad) / GRID_CELL);

  for (let cy = minCy; cy <= maxCy; cy++) {
    const yBits = cy & 0xffff;
    for (let cx = minCx; cx <= maxCx; cx++) {
      const key = ((cx & 0xffff) << 16) | yBits;
      const bucket = GRID_BUCKETS.get(key);
      if (bucket) {
        for (let i = 0; i < bucket.length; i++) {
          const e = bucket[i];
          if (e.hp > 0) {
            const dx = e.x - x;
            const dy = e.y - y;
            const lim = r + e.radius;
            if (dx * dx + dy * dy <= lim * lim) {
              results.push(e);
            }
          }
        }
      }
    }
  }
  return results;
}

function swapRemove(arr, idx) {
  const last = arr.length - 1;
  if (idx < last) arr[idx] = arr[last];
  arr.pop();
}

let NEXT_ATTACK_UID = 1;
function allocAttackUid() {
  NEXT_ATTACK_UID = (NEXT_ATTACK_UID + 1) & 0x3fffffff;
  return NEXT_ATTACK_UID;
}

// ============================================================================
// Underlying Engine Optimization #2: Offscreen Sprite Cache + 3D Skill Model Bakery
// Pre-renders rich 2.5D/3D composite weapon & elemental models onto offscreen
// 64x64 canvases so projectiles, orbitals, shurikens, boulders, fists, and
// meteors look like sculpted 3D game models with zero per-frame shader lag!
// ============================================================================
const IMG_CACHE = new Map();
const SILHOUETTE_CACHE = new Map();
const SKILL_MODEL_CACHE = new Map();

function getImg(src) {
  let img = IMG_CACHE.get(src);
  if (img) return img;
  img = new Image();
  img.src = src;
  IMG_CACHE.set(src, img);
  return img;
}

function getWhiteSilhouette(src, img) {
  let sil = SILHOUETTE_CACHE.get(src);
  if (sil) return sil;
  if (!img.complete || img.naturalWidth === 0) return null;
  const c = document.createElement("canvas");
  c.width = img.naturalWidth;
  c.height = img.naturalHeight;
  const cctx = c.getContext("2d");
  cctx.drawImage(img, 0, 0);
  cctx.globalCompositeOperation = "source-in";
  cctx.fillStyle = "#ffffff";
  cctx.fillRect(0, 0, c.width, c.height);
  SILHOUETTE_CACHE.set(src, c);
  return c;
}

// Pre-bake 3D Composite Skill Models (64x64 offscreen canvas per modelKey)
function getSkillModelCanvas(modelKey, primaryColor = "#00e5ff") {
  const cacheKey = `${modelKey}_${primaryColor}`;
  let c = SKILL_MODEL_CACHE.get(cacheKey);
  if (c) return c;

  c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const g = c.getContext("2d");
  const cx = 32, cy = 32;

  if (modelKey === "leaf_blade") {
    // 3D Sculpted Emerald Razor Leaf with central glowing vein, serrated edges & wind aura
    const grad = g.createLinearGradient(8, 32, 56, 32);
    grad.addColorStop(0, "#1b5e20");
    grad.addColorStop(0.45, "#00e676");
    grad.addColorStop(0.8, "#b9f6ca");
    grad.addColorStop(1, "#ffffff");
    g.fillStyle = grad;
    g.strokeStyle = "#e8f5e9";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(58, 32);
    g.quadraticCurveTo(36, 10, 8, 32);
    g.quadraticCurveTo(36, 54, 58, 32);
    g.closePath();
    g.fill();
    g.stroke();
    // 3D bevel highlight on upper half
    g.fillStyle = "rgba(255,255,255,0.32)";
    g.beginPath();
    g.moveTo(56, 32);
    g.quadraticCurveTo(36, 14, 12, 32);
    g.closePath();
    g.fill();
    // Central glowing vein & side ribs
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2.2;
    g.beginPath();
    g.moveTo(10, 32); g.lineTo(54, 32);
    g.moveTo(26, 32); g.lineTo(34, 21);
    g.moveTo(26, 32); g.lineTo(34, 43);
    g.moveTo(38, 32); g.lineTo(45, 24);
    g.moveTo(38, 32); g.lineTo(45, 40);
    g.stroke();
  } else if (modelKey === "fire_dragon_orb") {
    // 3D Multi-Layered Magma Fireball with white-hot core, swirling flame tongues & corona
    const radG = g.createRadialGradient(cx + 4, cy, 3, cx, cy, 28);
    radG.addColorStop(0, "#ffffff");
    radG.addColorStop(0.28, "#ffff00");
    radG.addColorStop(0.62, primaryColor === "#00e5ff" ? "#00b0ff" : "#ff3d00");
    radG.addColorStop(1, "rgba(183, 28, 28, 0)");
    g.fillStyle = radG;
    g.beginPath();
    g.arc(cx, cy, 28, 0, Math.PI * 2);
    g.fill();
    // Sculpted flame crest fins
    g.fillStyle = primaryColor === "#00e5ff" ? "#00e5ff" : "#ff9100";
    g.beginPath();
    g.moveTo(56, 32);
    g.quadraticCurveTo(38, 12, 6, 18);
    g.quadraticCurveTo(22, 32, 6, 46);
    g.quadraticCurveTo(38, 52, 56, 32);
    g.fill();
    // Inner white-gold core
    g.fillStyle = "#fffde7";
    g.beginPath();
    g.arc(38, 32, 10, 0, Math.PI * 2);
    g.fill();
  } else if (modelKey === "water_shuriken") {
    // 3D Faceted Crystal Water/Golden Shuriken with metallic core & specular bevels
    const isGold = primaryColor === "#ffd600";
    for (let k = 0; k < 4; k++) {
      g.save();
      g.translate(cx, cy);
      g.rotate((k * Math.PI) / 2);
      // Left facet (bright)
      g.fillStyle = isGold ? "#fff59d" : "#80d8ff";
      g.beginPath();
      g.moveTo(0, -29);
      g.lineTo(-9, -7);
      g.lineTo(0, 0);
      g.closePath();
      g.fill();
      // Right facet (deep 3D shade)
      g.fillStyle = isGold ? "#ff8f00" : "#0277bd";
      g.beginPath();
      g.moveTo(0, -29);
      g.lineTo(9, -7);
      g.lineTo(0, 0);
      g.closePath();
      g.fill();
      g.strokeStyle = "#ffffff";
      g.lineWidth = 1.5;
      g.beginPath();
      g.moveTo(0, -29); g.lineTo(-9, -7); g.lineTo(0, 0); g.lineTo(9, -7); g.closePath();
      g.stroke();
      g.restore();
    }
    // Central jewel ring
    g.fillStyle = "#ffffff";
    g.beginPath();
    g.arc(cx, cy, 5, 0, Math.PI * 2);
    g.fill();
  } else if (modelKey === "rock_polyhedron") {
    // 3D Faceted Obsidian/Crag Boulder with magma cracks & top-left 3D lighting
    g.save();
    g.translate(cx, cy);
    // Top-left lit facet
    g.fillStyle = "#bcaaa4";
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(-6, -24); g.lineTo(14, -18); g.lineTo(0, 0); g.closePath();
    g.fill();
    // Right mid facet
    g.fillStyle = "#8d6e63";
    g.beginPath();
    g.moveTo(14, -18); g.lineTo(24, 4); g.lineTo(8, 22); g.lineTo(0, 0); g.closePath();
    g.fill();
    // Bottom-left shadow facet
    g.fillStyle = "#4e342e";
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(0, 0); g.lineTo(8, 22); g.lineTo(-14, 18); g.closePath();
    g.fill();
    // Glowing lava/energy seams
    g.strokeStyle = primaryColor;
    g.lineWidth = 2.5;
    g.beginPath();
    g.moveTo(-6, -24); g.lineTo(0, 0); g.lineTo(24, 4);
    g.moveTo(0, 0); g.lineTo(-14, 18);
    g.stroke();
    // Outer outline
    g.strokeStyle = "#d7ccc8";
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(-22, -8); g.lineTo(-6, -24); g.lineTo(14, -18); g.lineTo(24, 4); g.lineTo(8, 22); g.lineTo(-14, 18); g.closePath();
    g.stroke();
    g.restore();
  } else if (modelKey === "fist_knuckle") {
    // 3D Sculpted Martial Aura Fist with shockwave rings & knuckle plates
    g.save();
    g.translate(cx, cy);
    const fg = g.createLinearGradient(-18, 0, 22, 0);
    fg.addColorStop(0, "rgba(255, 87, 34, 0.2)");
    fg.addColorStop(0.5, primaryColor);
    fg.addColorStop(1, "#fff59d");
    g.fillStyle = fg;
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2;
    // Main armored gauntlet block
    g.beginPath();
    g.roundRect(-12, -16, 26, 32, 7);
    g.fill();
    g.stroke();
    // 4 3D Knuckle ridges on front
    g.fillStyle = "#ffffff";
    for (let k = -11; k <= 11; k += 7) {
      g.beginPath();
      g.arc(14, k, 4.5, 0, Math.PI * 2);
      g.fill();
    }
    // Sonic Mach Cone in front of fist
    g.strokeStyle = "#ffeb3b";
    g.lineWidth = 2.5;
    g.beginPath();
    g.arc(10, 0, 22, -0.95, 0.95);
    g.stroke();
    g.restore();
  } else {
    // "astral_plasma_bolt": 3D Star-Core Energy Missile with dual intersecting rings & comet tail
    const rg = g.createRadialGradient(cx + 4, cy, 2, cx, cy, 24);
    rg.addColorStop(0, "#ffffff");
    rg.addColorStop(0.35, primaryColor);
    rg.addColorStop(1, "rgba(0,0,0,0)");
    g.fillStyle = rg;
    g.beginPath();
    g.arc(cx, cy, 24, 0, Math.PI * 2);
    g.fill();
    // 3D Tilted Orbital Rings
    g.strokeStyle = "#ffffff";
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(cx, cy, 20, 7, 0.55, 0, Math.PI * 2);
    g.stroke();
    g.strokeStyle = primaryColor;
    g.beginPath();
    g.ellipse(cx, cy, 20, 7, -0.55, 0, Math.PI * 2);
    g.stroke();
    // 4-point star diamond core
    g.fillStyle = "#ffffff";
    g.beginPath();
    g.moveTo(cx + 14, cy); g.lineTo(cx, cy - 8); g.lineTo(cx - 14, cy); g.lineTo(cx, cy + 8); g.closePath();
    g.fill();
  }

  SKILL_MODEL_CACHE.set(cacheKey, c);
  return c;
}

const MAP_CHUNK_CACHE = new Map();
function getStageChunkCanvas(st) {
  const cached = MAP_CHUNK_CACHE.get(st.id);
  if (cached) return cached;
  const gImg = getImg(st.groundTex);
  const pImg = getImg(st.pathTex);
  if (!gImg.complete || gImg.naturalWidth === 0 || !pImg.complete || pImg.naturalWidth === 0) return null;

  const chunk = document.createElement("canvas");
  chunk.width = 1024;
  chunk.height = 1024;
  const cctx = chunk.getContext("2d");
  cctx.imageSmoothingEnabled = false;
  const tileSize = 128;
  for (let r = 0; r < 8; r++) {
    for (let c = 0; c < 8; c++) {
      const hash = Math.abs(((c + 3) * 73856093) ^ ((r + 5) * 19349663)) % 100;
      const tex = hash < 18 ? pImg : gImg;
      cctx.drawImage(tex, c * tileSize, r * tileSize, tileSize, tileSize);
    }
  }
  MAP_CHUNK_CACHE.set(st.id, chunk);
  return chunk;
}

function drawPokemonSprite(ctx, pid, x, y, vx, vy, animTime, scale = 1.6, flashWhite = false, ringColor = null, hopY = 0) {
  const src = `./assets/pmd/${pid}.png`;
  const img = getImg(src);
  const meta = SPRITE_META[pid] || [0, 32, 32, 4];
  const wy = meta[0], fw = meta[1], fh = meta[2], fn = meta[3];

  if (!img.complete || img.naturalWidth === 0) {
    const iconImg = getImg(`./assets/portraits/${pid}.png`);
    if (iconImg.complete && iconImg.naturalWidth > 0) {
      const sz = 36 * scale;
      ctx.drawImage(iconImg, (x - sz * 0.5) | 0, (y - sz * 0.5 - hopY) | 0, sz | 0, sz | 0);
    }
    return;
  }
  let row = 0;
  if (vx > 0.01 || vx < -0.01 || vy > 0.01 || vy < -0.01) {
    const ang = Math.atan2(vx, vy);
    row = (Math.round(ang / 0.7853981633974483) % 8 + 8) % 8;
  }
  const col = ((animTime * 8) | 0) % (fn || 1);
  const sx = col * fw;
  const sy = wy + row * fh;
  const dw = (fw * scale) | 0;
  const dh = (fh * scale) | 0;
  const dx = (x - dw * 0.5) | 0;
  const dy = (y - dh * 0.5 - hopY) | 0;

  ctx.fillStyle = "rgba(0, 0, 0, 0.34)";
  ctx.fillRect((x - dw * 0.28) | 0, (y + dh * 0.28) | 0, (dw * 0.56) | 0, (dh * 0.14) | 0);

  if (ringColor) {
    ctx.strokeStyle = ringColor;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.arc(x | 0, (y + dh * 0.30) | 0, (dw * 0.38) | 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  ctx.drawImage(img, sx, sy, fw, fh, dx, dy, dw, dh);
  if (flashWhite) {
    const sil = getWhiteSilhouette(src, img);
    if (sil) {
      ctx.globalAlpha = 0.75;
      ctx.drawImage(sil, sx, sy, fw, fh, dx, dy, dw, dh);
      ctx.globalAlpha = 1.0;
    }
  }
}

// ============================================================================
// Underlying Engine Optimization #3: Throttled WebAudio Bus (Zero Node Leak!)
// ============================================================================
let bgmAudio = null;
let curBgmIdx = 0;

function playBgmTrack(idx, loop = true) {
  try {
    curBgmIdx = ((idx % BGM_TRACKS.length) + BGM_TRACKS.length) % BGM_TRACKS.length;
    const tr = BGM_TRACKS[curBgmIdx];
    if (bgmAudio) { bgmAudio.pause(); bgmAudio = null; }
    bgmAudio = new Audio(tr.file);
    bgmAudio.loop = loop;
    bgmAudio.volume = 0.42;
    bgmAudio.onended = () => {
      if (!loop && RUN && !RUN.over) nextStageBgm();
    };
    bgmAudio.play().catch(() => {});
    if (RUN) {
      addPopup(RUN.x, RUN.y - 52, `🎵 BGM：${tr.name}`, "#81d4fa", 1.08);
    }
  } catch (e) {}
}

function nextStageBgm() {
  if (RUN && RUN.stage && RUN.stage.bgmPool) {
    const pool = RUN.stage.bgmPool;
    const pick = pool[Math.floor(Math.random() * pool.length)];
    playBgmTrack(pick, false);
  } else {
    playBgmTrack((curBgmIdx + 1) % BGM_TRACKS.length, true);
  }
}

function playCry(pid) {
  try {
    const a = new Audio(`./assets/cries/${pid}.ogg`);
    a.volume = 0.45;
    a.play().catch(() => {});
  } catch (e) {}
}

let audioCtx = null;
let lastHitSfxTime = 0;
let lastGemSfxTime = 0;

function sfx(type) {
  try {
    const nowMs = performance.now();
    if (type === "hit") {
      if (nowMs - lastHitSfxTime < 68) return; // Throttle hit sfx to max 14/sec so multi-hit AoEs never lag WebAudio!
      lastHitSfxTime = nowMs;
    } else if (type === "gem") {
      if (nowMs - lastGemSfxTime < 55) return;
      lastGemSfxTime = nowMs;
    }
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === "suspended") audioCtx.resume();
    const now = audioCtx.currentTime;
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    if (type === "gem") {
      osc.type = "sine";
      osc.frequency.setValueAtTime(720, now);
      osc.frequency.exponentialRampToValueAtTime(1150, now + 0.05);
      gain.gain.setValueAtTime(0.06, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.055);
      osc.start(now); osc.stop(now + 0.06);
    } else if (type === "hit") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(160, now);
      osc.frequency.linearRampToValueAtTime(65, now + 0.045);
      gain.gain.setValueAtTime(0.045, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.045);
      osc.start(now); osc.stop(now + 0.05);
    } else if (type === "level") {
      osc.type = "square";
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(554, now + 0.07);
      osc.frequency.setValueAtTime(659, now + 0.14);
      osc.frequency.setValueAtTime(880, now + 0.21);
      gain.gain.setValueAtTime(0.09, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.34);
      osc.start(now); osc.stop(now + 0.35);
    } else if (type === "chest") {
      osc.type = "triangle";
      osc.frequency.setValueAtTime(523, now);
      osc.frequency.setValueAtTime(659, now + 0.08);
      osc.frequency.setValueAtTime(784, now + 0.16);
      osc.frequency.setValueAtTime(1046, now + 0.24);
      gain.gain.setValueAtTime(0.12, now);
      gain.gain.linearRampToValueAtTime(0.001, now + 0.45);
      osc.start(now); osc.stop(now + 0.46);
    }
  } catch (e) {}
}

function getStartingMoves(starterId) {
  const ls = STARTER_LEARNSETS[starterId]?.levelMoves || [];
  const lv1 = ls.filter(x => x[1] <= 1).map(x => x[0]);
  return lv1.slice(0, 2);
}

