      <b style="color:#00e5ff;">${(AWAKENING_CFG[curId] || []).map(a => `[${AWAKENING_RELIC_META[a.relic]?.short || '信物'}]${a.title.split('：')[1] || a.title}`).join(' · ')}</b>
